<script lang="ts">
	import gsap from 'gsap';
	import { onMount } from 'svelte';
	import flatpickr from 'flatpickr';
	import { French } from 'flatpickr/dist/l10n/fr.js';

	// ── Disponibilité ──
	let unavailableDates = $state<string[]>([]);
	let availableSlots = $state<Record<string, string[]>>({});

	onMount(async () => {
		const res = await fetch('/api/availability');
		const data = await res.json();
		unavailableDates = data.unavailableDates ?? [];
		availableSlots = data.availableSlots ?? {};
	});

	let availableTimeSlots = $derived.by(() => {
		return availableSlots[form.date] ?? [];
	});

	let dateInputEl = $state<HTMLInputElement | null>(null);
	let flatpickrInstance: any = null;

	let { isOpen = $bindable(false) } = $props();

	let step = $state(1);
	let loading = $state(false);
	let success = $state(false);

	let timeOpen = $state(false);
	let vehicleOpen = $state(false);
	let serviceOpen = $state(false);

	let timeButtonEl = $state<HTMLElement | null>(null);
	let vehicleButtonEl = $state<HTMLElement | null>(null);
	let serviceButtonEl = $state<HTMLElement | null>(null);

	type DropdownPos = { top: number; bottom: number; left: number; width: number; openUp: boolean };
	let dropdownPos = $state<DropdownPos>({ top: 0, bottom: 0, left: 0, width: 0, openUp: false });

	function openDropdown(buttonEl: HTMLElement, which: 'time' | 'vehicle' | 'service') {
		const rect = buttonEl.getBoundingClientRect();
		const spaceBelow = window.innerHeight - rect.bottom;
		const openUp = spaceBelow < 250;
		dropdownPos = {
			top: rect.bottom + 4,
			bottom: window.innerHeight - rect.top + 4,
			left: rect.left,
			width: rect.width,
			openUp
		};
		if (which === 'time') {
			timeOpen = !timeOpen;
			vehicleOpen = false;
			serviceOpen = false;
		}
		if (which === 'vehicle') {
			vehicleOpen = !vehicleOpen;
			timeOpen = false;
			serviceOpen = false;
		}
		if (which === 'service') {
			serviceOpen = !serviceOpen;
			timeOpen = false;
			vehicleOpen = false;
		}
	}

	function closeDropdowns() {
		timeOpen = false;
		vehicleOpen = false;
		serviceOpen = false;
	}

	let form = $state({
		date: '',
		time: '',
		datetime: '',
		vehicle: '',
		service: '',
		domicile: false,
		address: '',
		options: [] as string[],
		name: '',
		email: '',
		phone: '',
		payment: ''
	});

	const prices: Record<string, Record<string, number>> = {
		Citadine: { Intérieur: 40, Extérieur: 40, 'Int + Ext': 60 },
		Break: { Intérieur: 40, Extérieur: 40, 'Int + Ext': 60 },
		'4*4': { Intérieur: 50, Extérieur: 50, 'Int + Ext': 70 },
		Camionnette: { Intérieur: 50, Extérieur: 50, 'Int + Ext': 70 }
	};

	const optionPrices: Record<string, number> = {
		'Shampooing siège': 15,
		'Traitement cuir': 15,
		'Très sale / poils de chien': 10
	};

	const STATION_ADDRESS = 'Rue des Maraichers 5, 1070 Bruxelles';

	// Prix déplacement calculé (sera mis à jour quand on aura Google Maps)
	let deplacement = $state(0);

	let totalPrice = $derived.by(() => {
		let total = 0;
		if (form.vehicle && form.service && prices[form.vehicle]?.[form.service]) {
			total += prices[form.vehicle][form.service];
		}
		form.options.forEach((opt) => {
			total += optionPrices[opt] ?? 0;
		});
		if (form.domicile) total += deplacement;
		return total;
	});

	const timeSlots = ['08:00', '09:00', '10:00', '11:00', '13:00', '14:00', '15:00', '16:00'];
	const vehicles = ['Citadine', 'Break', '4*4', 'Camionnette'];
	const services = ['Intérieur', 'Extérieur', 'Int + Ext'];

	let overlayEl = $state<HTMLElement | null>(null);
	let contentEl = $state<HTMLElement | null>(null);

	$effect(() => {
		// Recrée flatpickr quand unavailableDates change ou quand isOpen change
		const dates = unavailableDates; // ← reactive dependency

		if (isOpen && dateInputEl) {
			// Détruit l'instance existante si elle existe
			if (flatpickrInstance) {
				flatpickrInstance.destroy();
				flatpickrInstance = null;
			}

			flatpickrInstance = flatpickr(dateInputEl, {
				locale: French,
				dateFormat: 'Y-m-d',
				altInput: true,
				altFormat: 'l j F Y',
				minDate: 'today',
				disable: [...dates],
				onChange: (selectedDates: Date[]) => {
					const date = selectedDates[0];
					if (!date) return;
					const y = date.getFullYear();
					const m = String(date.getMonth() + 1).padStart(2, '0');
					const d = String(date.getDate()).padStart(2, '0');
					form.date = `${y}-${m}-${d}`;
					// Vide l'heure — les nouveaux slots sont différents
					form.time = '';
				}
			});
		}

		if (!isOpen && flatpickrInstance) {
			flatpickrInstance.destroy();
			flatpickrInstance = null;
		}
	});

	$effect(() => {
		if (isOpen && overlayEl && contentEl) {
			gsap.fromTo(overlayEl, { opacity: 0 }, { opacity: 1, duration: 0.3, ease: 'power2.out' });
			gsap.fromTo(
				contentEl,
				{ y: 40, opacity: 0 },
				{ y: 0, opacity: 1, duration: 0.4, ease: 'expo.out', delay: 0.1 }
			);
		}
	});

	function close() {
		if (!overlayEl || !contentEl) return;
		closeDropdowns();
		gsap.to(contentEl, { y: 40, opacity: 0, duration: 0.3, ease: 'expo.in' });
		gsap.to(overlayEl, {
			opacity: 0,
			duration: 0.3,
			delay: 0.1,
			onComplete: () => {
				isOpen = false;
				step = 1;
				success = false;
				form = {
					date: '',
					time: '',
					datetime: '',
					vehicle: '',
					service: '',
					domicile: false,
					address: '',
					options: [],
					name: '',
					email: '',
					phone: '',
					payment: ''
				};
				deplacement = 0;
			}
		});
	}

	function nextStep() {
		closeDropdowns();
		if (step < 4) step++;
	}
	function prevStep() {
		closeDropdowns();
		if (step > 1) step--;
	}

	function toggleOption(opt: string) {
		form.options = form.options.includes(opt)
			? form.options.filter((o) => o !== opt)
			: [...form.options, opt];
	}

	async function submit() {
		loading = true;
		try {
			form.datetime = `${form.date}T${form.time}:00`;
			const res = await fetch('/api/booking', {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify({ ...form, totalPrice, deplacement })
			});
			const result = await res.json();
			if (result.success) {
				if (result.stripeUrl) {
					window.location.href = result.stripeUrl;
				} else {
					success = true;
				}
			}
		} catch (e) {
			console.error(e);
		} finally {
			loading = false;
		}
	}

	$effect(() => {
		if (isOpen) {
			document.documentElement.style.overflow = 'hidden';
		} else {
			document.documentElement.style.overflow = '';
		}
	});

	// Style commun pour les dropdowns
	function dropdownStyle(pos: DropdownPos) {
		if (pos.openUp) {
			return `bottom: ${pos.bottom}px; left: ${pos.left}px; width: ${pos.width}px; max-height: 240px;`;
		}
		return `top: ${pos.top}px; left: ${pos.left}px; width: ${pos.width}px; max-height: 240px;`;
	}

	// ── Google Places Autocomplete ──
	let addressSuggestions = $state<{ description: string; place_id: string }[]>([]);
	let showSuggestions = $state(false);
	let searchTimeout: ReturnType<typeof setTimeout>;

	async function searchAddress(query: string) {
		if (query.length < 3) {
			addressSuggestions = [];
			showSuggestions = false;
			return;
		}
		clearTimeout(searchTimeout);
		searchTimeout = setTimeout(async () => {
			const res = await fetch(`/api/places?input=${encodeURIComponent(query)}`);
			const data = await res.json();
			addressSuggestions = data.predictions ?? [];
			showSuggestions = addressSuggestions.length > 0;
		}, 300);
	}

	function selectAddress(description: string) {
		form.address = description;
		addressSuggestions = [];
		showSuggestions = false;
	}
</script>

{#if isOpen}
	<!-- Portals dropdowns — z-[600] -->
	{#if timeOpen}
		<div
			class="fixed z-600 overflow-y-auto rounded-xl border border-dark/10 bg-white shadow-xl"
			style={dropdownStyle(dropdownPos)}
		>
			{#if availableTimeSlots.length === 0}
				<p class="px-4 py-4 text-center text-sm text-dark/40">Aucun créneau disponible ce jour</p>
			{:else}
				{#each availableTimeSlots as slot}
					<button
						type="button"
						onclick={() => {
							form.time = slot;
							timeOpen = false;
						}}
						class="block w-full cursor-pointer px-4 py-3 text-left text-sm text-dark hover:bg-secondary-accent {form.time ===
						slot
							? 'font-semibold text-primary'
							: ''}"
					>
						{slot}
					</button>
				{/each}
			{/if}
		</div>
	{/if}

	{#if vehicleOpen}
		<div
			class="fixed z-600 overflow-y-auto rounded-xl border border-dark/10 bg-white shadow-xl"
			style={dropdownStyle(dropdownPos)}
		>
			{#each vehicles as v}
				<button
					type="button"
					onclick={() => {
						form.vehicle = v;
						vehicleOpen = false;
					}}
					class="block w-full cursor-pointer px-4 py-3 text-left text-sm text-dark hover:bg-secondary-accent {form.vehicle ===
					v
						? 'font-semibold text-primary'
						: ''}"
				>
					{v}
				</button>
			{/each}
		</div>
	{/if}

	{#if serviceOpen}
		<div
			class="fixed z-600 overflow-y-auto rounded-xl border border-dark/10 bg-white shadow-xl"
			style={dropdownStyle(dropdownPos)}
		>
			{#each services as s}
				<button
					type="button"
					onclick={() => {
						form.service = s;
						serviceOpen = false;
					}}
					class="block w-full cursor-pointer px-4 py-3 text-left text-sm text-dark hover:bg-secondary-accent {form.service ===
					s
						? 'font-semibold text-primary'
						: ''}"
				>
					{s}
				</button>
			{/each}
		</div>
	{/if}

	<!-- Overlay -->
	<div
		bind:this={overlayEl}
		class="fixed inset-0 z-300 flex items-center justify-center bg-dark/60 px-4"
		role="presentation"
		onclick={(e) => {
			if (e.target === e.currentTarget) close();
		}}
	>
		<div bind:this={contentEl} class="relative w-full max-w-lg rounded-3xl bg-white shadow-2xl">
			<!-- Close -->
			<button
				aria-label="button"
				type="button"
				onclick={close}
				class="absolute top-3 right-3 z-10 flex h-9 w-9 cursor-pointer items-center justify-center rounded-full bg-dark/5 text-dark/50 transition-colors hover:bg-dark/10 hover:text-dark"
			>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					width="18"
					height="18"
					fill="currentColor"
					viewBox="0 0 256 256"
				>
					<path
						d="M205.66,194.34a8,8,0,0,1-11.32,11.32L128,139.31,61.66,205.66a8,8,0,0,1-11.32-11.32L116.69,128,50.34,61.66A8,8,0,0,1,61.66,50.34L128,116.69l66.34-66.35a8,8,0,0,1,11.32,11.32L139.31,128Z"
					/>
				</svg>
			</button>

			<div class="max-h-[90vh] overflow-y-auto rounded-3xl p-8">
				{#if success}
					<div class="flex flex-col items-center gap-4 py-8 text-center">
						<div class="h-24 w-24">
							{@html `<svg id="Layer_1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 318.55 348.55"
	><path
		d="M0,0h318.55v348.55H0V0ZM190.58,235.9l2.49-3.04c6.32,3.58,12.43,6.29,19.64,7.13,18.68,2.16,33.04-10.79,36.76-28.61,12.1-2.34,20.58-11.93,20.38-24.32-.1-6.2-1.5-11.88-4.29-17.6,6.52-8.07,11.61-24.84,6.37-34.87,8.81-13.3,19.47-30.49,21.32-46.15,2.45-.22,4.8-.71,6.56-1.87,3.76-2.48,4.28-7.23,1.62-10.84,12.09-10.54,15.17-28.96,8.46-43.12-2.44-5.16-6.75-8.45-12.24-9.3-4.19-5.68-11.06-7.95-17.6-5.93-4.44-3.53-9.88-4-14.82-1.35-6.24,3.35-9.6,9.83-9.57,16.93-6,2.73-8.78,8.63-8.09,15.17,1.03,9.67,6.93,17.77,14.98,23.3-2.16,5.88.45,11.59,6.22,13.99.36,8.25-6.72,20.15-11.11,26.58-4.96-3.36-10.03-5.18-15.78-6-.1-6.75-2.85-13.01-8.53-17.36,8.26-25.39-7.45-48.65-29.12-61,.42-5.88-3.32-10.51-8.88-11.86-4.73-1.15-9.54-.05-12.69,3.84-21.32-4.72-47.69,2.83-55.58,25.32l-10.27-1.39c-8.78-1.19-16.98.26-25.38,2.51-3.18.85-6.4.84-8.71,3.24-4.42,4.6-5.52,10.53-2.58,16.31,2.94,5.78,7.58,10.12,13.3,13.51l-2.73,5.14c-5.03-1.03-9.47.11-13.53,2.85-8.51,5.72-12.5,15.97-11.16,25.83l-7.94,3.56c-6.88-11.64-11.21-24.69-13.31-37.97-1.1-6.97,8.61-4.39,6.59-16.16,10.44-5.98,19.35-21.03,14.29-32.54-1.05-2.39-3.55-3.78-5.82-5.14,1.13-7.96-2.24-15.84-9.27-19.41-5.04-2.57-10.81-2.23-15.09,1.49-6.29-2.15-12.4.37-15.79,5.82-5.39.17-9.6,2.98-12.11,7.5C.31,33.16,2.03,53.24,13.66,63.02c-2.5,3.12-2.14,6.9.15,9.91,1.87,2.45,4.96,3.79,7.92,4.89.25,15.21,8.45,36.45,15.85,49.82,2.13,3.84,4.62,6.98,7.98,9.71-.64,8.32,1.27,16.16,5.18,23.32-12.78,14.43-12.25,34.97,3.65,46.16,5.38,3.79,11.33,5.93,18.12,6.1,2.65,13.09,12.22,19.36,25.25,20.48-1.61,14.7,3.95,31.56,9.21,45.25-6.25,2.55-9.07,8.56-6.03,14.83l-13.58,5.87c-9.84-1.39-18.67,4.04-22.86,12.83-3,6.3-2.85,12.96.04,19.2.83,1.8,1.5,3.38,3.67,4.23,4.94,1.95,10.12,2.65,15.64,2.78,16.24.38,32.26-2.69,47.4-8.54,3.73-1.44,6.75-3.72,10.03-5.76,1.74-1.08,2.87-1.76,3.02-4.27.48-8.02-.89-20.59-5.64-27.48,1.31-2.71,2.2-5.88.98-8.69-2.05-4.75-6.63-7.03-12.15-6.45l-5.73-23.13c-1.63-6.58-2.68-13.04-2.68-19.77,9.02,2.36,17.4,3.05,25.99.59,7.26,6.97,16.75,10.02,26.62,9.37l16.19,3